window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6c31c179f62efeff"]={"versions": [{"id": "FIG-6c31c179f62efeff", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Dateistruktur-Diagramm im Kontext der AUTOSAR Classic Platform (SWS Memory Mapping). Das Diagramm stellt die kompilierungsrelevante Include-Abhängigkeit zwischen dem Quellcode einer Software-Komponente (SWC) und ihrer typspezifischen Memory-Mapping-Header-Datei dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Entitäten sowie eine gerichtete Beziehung:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Repräsentiert das Quellcode-Artefakt bzw. die Implementierungsdatei der Software-Komponente (gekennzeichnet mit Dateisymbol).</li>\n<li><code>{componentTypeName}_MemMap.h</code>: Header-Datei-Artefakt mit Stereotyp <code>«header»</code>, wobei <code>{componentTypeName}</code> als Platzhalter für den konkreten Typnamen der Software-Komponente dient.</li>\n<li><code>«includes»</code>: Gestrichelte gerichtete Abhängigkeitspfeillinie von <code>SWC</code> auf <code>{componentTypeName}_MemMap.h</code>, die das Einbinden via Präprozessor-Direktive <code>#include</code> abbildet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit bzw. Präprozessorphase. Die Quelldatei der Software-Komponente bindet die Header-Datei <code>{componentTypeName}_MemMap.h</code> wiederholt vor und nach zu mappenden Code- oder Datenabschnitten ein, um compilerspezifische Pragmas für Speichersektionen zu setzen. Das Diagramm modelliert keinen sequenziellen Laufzeitablauf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen sicherstellen, dass jede Software-Komponente ausschließlich ihren eigenen typspezifischen Header <code>{componentTypeName}_MemMap.h</code> inkludiert, sofern die typspezifische Memory-Mapping-Strategie gewählt wurde. Der Header kapselt die Zuordnung von Symbolen (Funktionen, Variablen, Konstanten) zu Speichersektionen. Präprozessor-Makros müssen vor dem erneuten Inkludieren passend definiert bzw. undefiniert werden.</p>"}, {"id": "FIG-fe3e6407307cd9f3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Dateistruktur-Diagramm im Kontext der AUTOSAR Classic Platform (SWS Memory Mapping). Das Diagramm stellt die kompilierungsrelevante Include-Abhängigkeit zwischen dem Quellcode einer Software-Komponente (SWC) und ihrer typspezifischen Memory-Mapping-Header-Datei dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei Entitäten sowie eine gerichtete Beziehung:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Repräsentiert das Quellcode-Artefakt bzw. die Implementierungsdatei der Software-Komponente (gekennzeichnet mit Dateisymbol).</li>\n<li><code>{componentTypeName}_MemMap.h</code>: Header-Datei-Artefakt mit Stereotyp <code>«header»</code>, wobei <code>{componentTypeName}</code> als Platzhalter für den konkreten Typnamen der Software-Komponente dient.</li>\n<li><code>«includes»</code>: Gestrichelte gerichtete Abhängigkeitspfeillinie von <code>SWC</code> auf <code>{componentTypeName}_MemMap.h</code>, die das Einbinden via Präprozessor-Direktive <code>#include</code> abbildet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsverhältnis zur Kompilierzeit bzw. Präprozessorphase. Die Quelldatei der Software-Komponente bindet die Header-Datei <code>{componentTypeName}_MemMap.h</code> wiederholt vor und nach zu mappenden Code- oder Datenabschnitten ein, um compilerspezifische Pragmas für Speichersektionen zu setzen. Das Diagramm modelliert keinen sequenziellen Laufzeitablauf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen sicherstellen, dass jede Software-Komponente ausschließlich ihren eigenen typspezifischen Header <code>{componentTypeName}_MemMap.h</code> inkludiert, sofern die typspezifische Memory-Mapping-Strategie gewählt wurde. Der Header kapselt die Zuordnung von Symbolen (Funktionen, Variablen, Konstanten) zu Speichersektionen. Präprozessor-Makros müssen vor dem erneuten Inkludieren passend definiert bzw. undefiniert werden.</p>"}], "trans": [{"from": "FIG-6c31c179f62efeff", "to": "FIG-fe3e6407307cd9f3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
